# Generated by build.py from recipe.yml for recipe sftp-upload-a-batch-and-verify-it. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'batch' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'batch/notes.txt'), "release notes`n")
[IO.File]::WriteAllText((Join-Path $PWD 'batch/config.ini'), "[app]`nname = demo`n")
[IO.File]::WriteAllText((Join-Path $PWD 'batch/data.csv'), "id,name`n1,a`n2,b`n")
[IO.File]::WriteAllText((Join-Path $PWD 'makeblobs.sh'), "head -c 1500 /dev/zero > batch/blob.bin`nmkdir -p short`nhead -c 1000 /dev/zero > short/blob.bin`n")
[IO.File]::WriteAllText((Join-Path $PWD 'upload.sh'), "#!/bin/sh`n# Usage: sh upload.sh PORT DIR [NAME...]`n# Uploads the named files of DIR (all of them when none is named) to /inbox/ on a surl`n# whose host key is pinned: the fingerprint comes from host_key.pub, so a different key is refused.`nset -e`nport=`$1; dir=`$2; shift 2`n[ `$# -gt 0 ] || set -- `$(ls `"`$dir`")`npin=`$(ssh-keygen -l -f host_key.pub | cut -d' ' -f2 | sed 's/^SHA256://')`n# One curl for the whole batch: -T takes a glob, and a URL ending in / keeps each file's name.`nlist=`$(echo `"`$@`" | tr ' ' ',')`ncurl -s -S --hostpubsha256 `"`$pin`" -u alice:s3cret --ftp-create-dirs \`n  -T `"`$dir/{`$list}`" `"sftp://127.0.0.1:`$port/inbox/`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'compare.sh'), "#!/bin/sh`n# Usage: sh compare.sh PORT DIR`n# Lists /inbox/ on the server and compares every name and size with the files of DIR.`nset -e`nport=`$1; dir=`$2`npin=`$(ssh-keygen -l -f host_key.pub | cut -d' ' -f2 | sed 's/^SHA256://')`nfor name in `$(ls `"`$dir`"); do echo `"`$name `$(wc -c < `"`$dir/`$name`" | tr -d ' ')`"; done | LC_ALL=C sort > local.txt`ncurl -s -S --hostpubsha256 `"`$pin`" -u alice:s3cret `"sftp://127.0.0.1:`$port/inbox/`" > listing.txt`nawk '{print `$NF, `$5}' listing.txt | LC_ALL=C sort > remote.txt`nif diff local.txt remote.txt > diff.txt; then`n  echo `"all `$(wc -l < local.txt | tr -d ' ') files match`"`n  cat remote.txt`nelse`n  echo `"MISMATCH`"`n  cat diff.txt`n  exit 1`nfi`n")
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f host_key'
cmd /c 'sh makeblobs.sh'
$server0 = Start-Process surl -ArgumentList '--hostkey', 'host_key', '--user', 'alice:s3cret', '--allow-uploads', '--list-directories', 'sftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh upload.sh 8080 batch && sh compare.sh 8080 batch } finally { Stop-Process $server0 }
